const (
	projectNameMinLen = 3
	projectNameMaxLen = 32
	// Repo names share the project-name shape but are more permissive on
	// length: a single char is fine (e.g. an "x" scratch repo) and they
	// can run longer than the 32-char project cap.
	repoNameMinLen = 1
	repoNameMaxLen = 64
)

// normalizeProjectName trims surrounding space and validates the canonical
// project-name shape. Project names are human-facing identifiers, not display
// strings: keep this helper at the resource boundary so every caller follows
// the same rules.
func normalizeProjectName(name string) (string, error) {
	return normalizeName("project name", name, projectNameMinLen, projectNameMaxLen, false)
}

// foldProjectName lowercases and validates a project name for case-insensitive
// lookup. Creation uses normalizeProjectName, which rejects uppercase to keep
// stored names canonical; lookups instead fold case so "Widgets" resolves the
// stored "widgets". The returned value is the canonical (lowercase) form, ready
// to match against the lower(name) unique index.
func foldProjectName(name string) (string, error) {
	return normalizeName("project name", strings.ToLower(strings.TrimSpace(name)), projectNameMinLen, projectNameMaxLen, false)
}

// NormalizeRepoName trims and validates a native repo name against the same
// shape as project names — lowercase letters, digits, '-', and interior '.'
// (e.g. "entire-trails.el"), no leading or trailing '-'/'.', no consecutive
// dots, not a raw ULID — differing only in length bounds and the dot
// allowance. Rejecting uppercase at create time is what lets /et/ paths be
// folded to lowercase on resolution (see authn.CanonicalizeRepoURL) without
// collapsing two distinct repos: no new case-colliding pair can be created.
// Dots are safe because repo names resolve to a ULID and never become a
// filesystem path or git ref (objects are content-addressed by RepoID); the
// ".."/edge-dot bans keep names clean in URLs and clone output regardless.
func NormalizeRepoName(name string) (string, error) {
	return normalizeName("repo name", name, repoNameMinLen, repoNameMaxLen, true)
}

// normalizeName is the shared shape check behind project and repo names.
// kind names the entity for error messages; minLen/maxLen bound the length;
// allowDot permits interior '.' (repo names) while still banning leading,
// trailing, and consecutive dots.
func normalizeName(kind, name string, minLen, maxLen int, allowDot bool) (string, error) {
	trimmed := strings.TrimSpace(name)
	if len(trimmed) < minLen || len(trimmed) > maxLen {
		return "", fmt.Errorf("%s %q must be %d-%d characters: %w", kind, trimmed, minLen, maxLen, ErrInvalidName)
	}
	if trimmed[0] == '-' || trimmed[len(trimmed)-1] == '-' {
		return "", fmt.Errorf("%s %q must not start or end with '-': %w", kind, trimmed, ErrInvalidName)
	}
	if allowDot && (trimmed[0] == '.' || trimmed[len(trimmed)-1] == '.') {
		return "", fmt.Errorf("%s %q must not start or end with '.': %w", kind, trimmed, ErrInvalidName)
	}
	for _, r := range trimmed {
		if r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '-' {
			continue
		}
		if allowDot && r == '.' {
			continue
		}
		allowed := "lowercase letters, digits, and '-'"
		if allowDot {
			allowed = "lowercase letters, digits, '.', and '-'"
		}
		return "", fmt.Errorf("%s %q must contain only %s: %w", kind, trimmed, allowed, ErrInvalidName)
	}
	if allowDot && strings.Contains(trimmed, "..") {
		return "", fmt.Errorf("%s %q must not contain consecutive dots: %w", kind, trimmed, ErrInvalidName)
	}
	if model.LooksLikeRawULID(trimmed) {
		return "", fmt.Errorf("%s %q must not be a raw ULID: %w", kind, trimmed, ErrInvalidName)
	}
	return trimmed, nil
}

