// GetProjectByName resolves a project by name, case-insensitively. Project
// names are globally unique on lower(name) (migration 023) and lowercase-only
// at create, so the input is folded (foldProjectName) and matched against the
// lower(name) index. O(1).
func (s *Store) GetProjectByName(ctx context.Context, name string) (*model.Project, error) {
	return s.getProjectByName(ctx, name, postgres.CurrentReadAOST)
}

// GetProjectByNameFollowerRead is GetProjectByName served from the nearest CRDB
// replica (~4.8s stale), with a fresh fallback on ANY error — including
// ErrNotFound, so a project created just before a GET /projects?name= still
// resolves rather than 404ing. Same fresh-on-miss contract as
// GetProjectFollowerRead.
func (s *Store) GetProjectByNameFollowerRead(ctx context.Context, name string) (*model.Project, error) {
	p, err := s.getProjectByName(ctx, name, s.followerAOST())
	if err == nil {
		return p, nil
	}
	if !errors.Is(err, ErrNotFound) && ctx.Err() == nil {
		slogutil.Warn(ctx, "resource: get-project-by-name follower read failed, falling back to leaseholder read",
			slog.String("error", err.Error()))
	}
	return s.getProjectByName(ctx, name, postgres.CurrentReadAOST)
}

func (s *Store) getProjectByName(ctx context.Context, name string, aost postgres.AOST) (*model.Project, error) {
	name, err := foldProjectName(name)
	if err != nil {
		return nil, err
	}

	p := &model.Project{}
	err = s.pool.QueryRow(ctx,
		`SELECT id, name, owner_type, owner_id, region, created_at FROM projects `+string(aost)+`WHERE lower(name) = $1`, name,
	).Scan(&p.ID, &p.Name, &p.OwnerType, &p.OwnerID, &p.Region, &p.CreatedAt)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, fmt.Errorf("project %q: %w", name, ErrNotFound)
		}
		return nil, fmt.Errorf("get project by name: %w", err)
	}
	return p, nil
}

